import{_ as n,l as s,o as e,c as l,v as t,p as i,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"延迟槽对照","description":"","frontmatter":{"title":"延迟槽对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/delay-slot.md","filePath":"cs/delay-slot.md","lastUpdated":1789023840000}'),A={name:"cs/delay-slot.md"};function E(h,a,B,_,m,S){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="延迟槽对照" tabindex="-1">延迟槽对照 <a class="header-anchor" href="#延迟槽对照" aria-label="Permalink to &quot;延迟槽对照&quot;">​</a></h1><div class="epigraph"><p>把分支后面那一条规定为总是执行，硬件就少冲刷一拍；代价是 ISA 把流水线深度暴露给程序员。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (MIPS)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/pipeline-exception">上一课</a>要求冲刷年轻指令、按序报告 EPC。预测失败时同样冲刷。<a href="/cs/control-hazard-predict">控制冒险与分支预测</a>已把延迟槽划成「主干不用」。本课不重讲精确异常。缺口是对照：早期 RISC 为什么用软件可见的延迟槽代替冲刷，以及当代核为什么放弃它。本课只钉这一对照，不把延迟槽写进后课默认 ISA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五级里条件在 EX 才齐，顺序取指已经灌进 IF/ID。预测加冲刷要扔掉这些指令。另一条路：ISA 规定分支后的一条（或两条）<strong>无论方向如何都执行</strong>，编译器往槽里填无关指令或把目标/顺序路径上安全的指令上移。硬件少一次冲刷，CPI 看起来更好。</p><p>缺口不是新的预测器，而是承认：<strong>这把流水线级数写进了二进制兼容</strong>。加深流水线、超标量、延迟槽条数对不上号时，硬件仍得模拟旧语义，比冲刷更贵。</p><p><span class="marginnote">MIPS I 的 load 延迟槽与分支延迟槽是同一思想：把 RAW 或控制空档交给软件。RISC-V 整数基础没有程序员可见延迟槽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分支延迟槽：取指顺序上紧跟分支的那条，在目标或 PC+8 之前执行。空槽填 <code>nop</code>。编译器若找不到无关指令，槽里就是浪费的一拍——与硬件气泡同价，但编码占空间。</p>',9)),(e(),i(c,null,{default:o(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22%E5%88%86%E6%94%AF%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20SLOT%5B%22%E5%BB%B6%E8%BF%9F%E6%A7%BD%EF%BC%9A%E6%80%BB%E6%89%A7%E8%A1%8C%22%5D%0A%20%20SLOT%20--%3E%20T%5B%22%E6%88%90%E5%8A%9F%EF%BC%9A%E5%8E%BB%E7%9B%AE%E6%A0%87%22%5D%0A%20%20SLOT%20--%3E%20F%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E5%8E%BB%E6%A7%BD%E4%B9%8B%E5%90%8E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与预测对照：槽是架构承诺；预测是微结构猜测，错了冲刷，ISA 仍是「分支下一条即目标或顺序」。精确异常：槽里的指令若已提交，EPC 规则必须写明异常发生在分支还是槽——又一份兼容负担。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟槽在单发射、浅流水、编译器能填满槽时划算。槽填不满或流水线加深后，平均收益下降，而所有未来实现都要遵守。预测器加 BTB 把控制冒险的平均损失压到低于「永远执行一条可能无用的指令」，且不污染 ISA。</p><p><a href="/cs/tournament-predict">锦标赛预测</a>的误预测率足够低时，冲刷的阿姆达尔项小于强制执行槽。这是定量选择，不是审美。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不要求后课程序使用延迟槽，也不把 MIPS 延迟槽例外（annul 位）写进主干。RISC-V 课已经按无槽 ISA 讲转发与预测。浮点多周期的软件流水是编译调度，不是 ISA 槽。</p><p>后课默认：控制冒险靠预测与冲刷；CPI 公式按误预测损失计数。延迟槽只作历史对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>延迟槽把空档写成 ISA：槽内指令总执行，硬件少冲刷。</li><li>流水线深度与发射宽度一变，槽语义成为包袱。</li><li>主干继续用预测；下一课把停顿写成 CPI 与阿姆达尔。</li><li>出处：Patterson and Hennessy, <em>COD</em> MIPS 延迟槽；Hennessy and Patterson, <em>CA:AQA</em>；对照 RISC-V 无槽约定。</li></ul>',9))])}const u=n(A,[["render",E]]);export{P as __pageData,u as default};
